import sys

def rot_brute(grid):
    m, n = len(grid), len(grid[0])
    minutes = 0
    while True:
        changed = False
        new = [row[:] for row in grid]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 2:
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and new[ni][nj] != 2:
                            new[ni][nj] = 2
                            changed = True
        grid = new
        if not changed:
            break
        minutes += 1
    for row in grid:
        if 1 in row:
            return -1
    return minutes

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(rot_brute(grid))

import sys
from collections import deque

def rot_opt(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                q.append((i, j))
            elif grid[i][j] == 1:
                fresh += 1
    if fresh == 0:
        return 0
    minutes = 0
    while q and fresh > 0:
        minutes += 1
        for _ in range(len(q)):
            i, j = q.popleft()
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    grid[ni][nj] = 2
                    fresh -= 1
                    q.append((ni, nj))
    return -1 if fresh > 0 else minutes

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(rot_opt(grid))

import sys
from collections import deque

def rot_best(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    dist = [[-1] * n for _ in range(m)]
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                q.append((i, j))
                dist[i][j] = 0
            elif grid[i][j] == 1:
                fresh += 1
    if fresh == 0:
        return 0
    ans = 0
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and dist[ni][nj] == -1 and grid[ni][nj] == 1:
                dist[ni][nj] = dist[i][j] + 1
                ans = max(ans, dist[ni][nj])
                fresh -= 1
                q.append((ni, nj))
    return -1 if fresh > 0 else ans

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(rot_best(grid))
